package com.vomatt.entity.common;

import jakarta.persistence.Column;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;
import jakarta.persistence.PrePersist;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.experimental.SuperBuilder;
import org.hibernate.annotations.UuidGenerator;
import org.hibernate.id.uuid.UuidVersion7Strategy;

import java.time.OffsetDateTime;
import java.util.UUID;

/**
 * Base class for all entities, providing id and created_at. id is a UUID v7 generated by Hibernate
 * (time-ordered and monotonic within a millisecond, which keyset pagination relies on); ids inserted by native
 * queries come from the same generator through {@link #newTimeOrderedId()}.
 */
@Getter
@SuperBuilder
@NoArgsConstructor
@MappedSuperclass
public abstract class BaseEntity {

    @UuidGenerator(style = UuidGenerator.Style.VERSION_7)
    @Id
    @Column(name = "id", columnDefinition = "uuid", updatable = false, nullable = false)
    private UUID id;

    @Column(name = "created_at", updatable = false, nullable = false)
    private OffsetDateTime createdAt;

    // Single clock read per insert; AuditableEntity copies it into updated_at
    @PrePersist
    void stampCreatedAt() {
        if (createdAt == null) {
            createdAt = OffsetDateTime.now();
        }
    }

    /** A new UUID v7 id from the generator {@code @UuidGenerator} uses, for rows inserted by native queries. */
    public static UUID newTimeOrderedId() {
        // The strategy ignores its session argument
        return UuidVersion7Strategy.INSTANCE.generateUuid(null);
    }
}
